"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import type { NotificationPrefs } from "./prefs";

/** Save notification preferences from the settings form. */
export async function updateNotificationPrefs(
  prev: unknown,
  formData: FormData,
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  const prefs: NotificationPrefs = {
    email: formData.get("email") === "on",
    product: formData.get("product") === "on",
    security: formData.get("security") === "on",
  };
  await db.user.update({ where: { id: user.id }, data: { notificationPrefs: prefs } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}
/**
 * Notification-preference types + helpers. Plain module (safe to import from
 * client and server components; the `"use server"` action file may only export
 * async functions, so these live here).
 *
 * Persisted to `User.notificationPrefs` (Json). Three toggle groups:
 *   - email:    transactional/account email (invoices, deploys)
 *   - product:  product news & announcements
 *   - security: security alerts (new logins, token changes)
 */
export type NotificationPrefs = {
  email: boolean;
  product: boolean;
  security: boolean;
};

export const DEFAULT_PREFS: NotificationPrefs = { email: true, product: true, security: true };

/** Normalise whatever is stored in the Json column into a typed prefs object. */
export function normalizePrefs(raw: unknown): NotificationPrefs {
  const p = (raw ?? {}) as Record<string, unknown>;
  return {
    email: typeof p.email === "boolean" ? p.email : DEFAULT_PREFS.email,
    product: typeof p.product === "boolean" ? p.product : DEFAULT_PREFS.product,
    security: typeof p.security === "boolean" ? p.security : DEFAULT_PREFS.security,
  };
}
"use server";

import { revalidatePath } from "next/cache";
import { randomBytes } from "node:crypto";
import { db } from "./db";
import { requireUser } from "./auth";
import { hashToken, TOKEN_PREFIX } from "./api-auth";

/**
 * Customer API-token server actions.
 *
 * Tokens are `nxe_<prefix>_<random>`. Only the sha256 hash + short prefix are
 * persisted; the full token is shown exactly once at creation time.
 */

const VALID_SCOPES = ["read", "write"] as const;

/** Create a token. Returns the plaintext ONCE — it is never retrievable again. */
export async function createApiToken(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; token?: string; name?: string }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  if (name.length < 1 || name.length > 60) return { error: "Token name: 1–60 characters." };

  const scopesRaw = formData.getAll("scopes").map(String);
  const scopes = scopesRaw.filter((s): s is (typeof VALID_SCOPES)[number] =>
    (VALID_SCOPES as readonly string[]).includes(s),
  );
  if (scopes.length === 0) scopes.push("read");

  // Optional expiry in days.
  const expiresDays = Number(formData.get("expiresDays") ?? "");
  let expiresAt: Date | null = null;
  if (Number.isFinite(expiresDays) && expiresDays > 0) {
    expiresAt = new Date(Date.now() + expiresDays * 24 * 60 * 60 * 1000);
  }

  const prefix = randomBytes(4).toString("hex"); // 8-char public prefix
  const secret = randomBytes(24).toString("base64url");
  const fullToken = `${TOKEN_PREFIX}_${prefix}_${secret}`;

  await db.apiToken.create({
    data: {
      userId: user.id,
      name,
      prefix,
      tokenHash: hashToken(fullToken),
      scopes,
      expiresAt,
    },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.api_token_created", detail: name } });
  revalidatePath("/dashboard/settings");
  return { token: fullToken, name };
}

/** Revoke a token owned by the current user. */
export async function revokeApiToken(tokenId: string): Promise<void> {
  const user = await requireUser();
  await db.apiToken.updateMany({
    where: { id: tokenId, userId: user.id },
    data: { revoked: true },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.api_token_revoked" } });
  revalidatePath("/dashboard/settings");
}
import { createHash } from "node:crypto";
import { db } from "./db";
import type { User } from "@prisma/client";

/**
 * Bearer-token authentication for the public REST API (`/api/v1/*`).
 *
 * Tokens are formatted `nxe_<prefix>_<random>` and only their sha256 hash is
 * stored (never the plaintext). Given an incoming request, resolve the bearer
 * token to its owning user, honouring `revoked` and `expiresAt`, and stamp
 * `lastUsedAt`.
 */

export const TOKEN_PREFIX = "nxe";

/** Extract the raw bearer token from an `Authorization: Bearer …` header. */
export function extractBearer(req: Request): string | null {
  const header = req.headers.get("authorization") ?? req.headers.get("Authorization");
  if (!header) return null;
  const match = /^Bearer\s+(.+)$/i.exec(header.trim());
  return match ? match[1].trim() : null;
}

/** sha256 hex hash of a token — the value stored in `ApiToken.tokenHash`. */
export function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

export type ApiAuthResult =
  | { ok: true; user: User; tokenId: string; scopes: string[] }
  | { ok: false; status: number; error: string };

/**
 * Authenticate an API request by its bearer token.
 * Returns the resolved user + token scopes, or a structured error with an
 * appropriate HTTP status for the route to return.
 */
export async function authenticateApiToken(req: Request): Promise<ApiAuthResult> {
  const raw = extractBearer(req);
  if (!raw) return { ok: false, status: 401, error: "Missing bearer token" };
  if (!raw.startsWith(`${TOKEN_PREFIX}_`)) {
    return { ok: false, status: 401, error: "Invalid token format" };
  }

  const tokenHash = hashToken(raw);
  const token = await db.apiToken.findUnique({
    where: { tokenHash },
    include: { user: true },
  });

  if (!token) return { ok: false, status: 401, error: "Invalid token" };
  if (token.revoked) return { ok: false, status: 401, error: "Token has been revoked" };
  if (token.expiresAt && token.expiresAt < new Date()) {
    return { ok: false, status: 401, error: "Token has expired" };
  }
  if (!token.user || token.user.suspended) {
    return { ok: false, status: 403, error: "Account unavailable" };
  }

  // Best-effort lastUsedAt stamp — never block the request on this write.
  db.apiToken
    .update({ where: { id: token.id }, data: { lastUsedAt: new Date() } })
    .catch(() => {});

  return { ok: true, user: token.user, tokenId: token.id, scopes: token.scopes };
}

/**
 * Whether an authenticated token carries a given scope.
 *
 * Backward-compat policy: a token with NO scopes recorded (empty array) is
 * treated as FULL ACCESS — tokens minted before scoping was enforced keep
 * working. Otherwise the token must carry:
 *   - the exact requested scope (e.g. `servers:read`), or
 *   - the global wildcard `*`, or
 *   - the resource wildcard `servers:*` (covers `servers:read`), or
 *   - the generic `read` scope, which satisfies any `*:read` request.
 */
export function tokenHasScope(auth: ApiAuthResult, scope: string): boolean {
  if (!auth.ok) return false;
  const scopes = auth.scopes;
  if (!scopes || scopes.length === 0) return true; // legacy full-access token
  if (scopes.includes("*") || scopes.includes(scope)) return true;
  const [resource, action] = scope.split(":");
  if (resource && scopes.includes(`${resource}:*`)) return true;
  if (action === "read" && scopes.includes("read")) return true;
  return false;
}

